CHANGELOG = '## [1.143.0] - a vault rack is blue painted steel, its bricks pale\n\nThe walker, of the vault after 1.142.0: "that vault room needs some love", with four photographs -- a gold vault\'s\nracks of blue painted steel in rows, a room walled in deposit boxes, white wall shelving, a stack of Federal Reserve\nbricks -- and of Deli Counter 0.286.0\'s racks: "we wouldn\'t have cash inside a wooden bookcase, that looks very\nwrong". 1.142.0 drew a brick\'s sides a banknote\'s face green, dark, on a bare grey rack that read near black.\n\n### Changed\n- **A brick\'s sides are pale** (`_shelf_stock.VAULT_PALETTE`\'s `notes`: 0.58, 0.56, 0.46). They are the edges of a\n  thousand notes, paper-grey under clear wrap, as in the walker\'s photograph. The bands are as dark as they must be\n  to read against them, each still its denomination\'s strap colour ($10\'s yellow the closest, 1.43).\n- **A vault rack is painted and open-backed** (`shelving`, stock `vault`; `VAULT_RACK_RGB` 0.03, 0.05, 0.28,\n  `VAULT_RACK_KIND` `metal_painted`). Frame and boards in the deep blue of the gold vault\'s racks, one material with\n  its colour in the vertex, whatever the style; no back panel, as racks in a row are loaded from both sides. A rack is\n  two materials, the paint and the money, where it was three.\n- **The navy deposit bag is grey canvas** (`bag_grey`): navy on a blue rack would not read.\n\n### Measured\n- The 1.8 x 0.5 x 1.9 rack: 2,184 triangles (2,228 with its back panel), 0 coincident pairs.\n\n### Not yet drawn\n- The wrap\'s printed blue ("THE FEDERAL RESERVE ... WARNING" on clear film, in the photograph). The bricks read as\n  pale banded blocks.\n\n### Tests\n- `tests/test_shelf_stock_vault.py`: the notes and bags read against the rack\'s paint, every band against the notes;\n  the notes pale and near grey, the rack dark and blue (fails on 1.142.0).\n- `tests/test_vault_money_and_frames.py`: a vault rack is the paint and the money, and has no back panel.\n\n'
OLD_VERSION, NEW_VERSION = '1.142.0', '1.143.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (REPO / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: zoo/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: zoo/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: zoo/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (REPO / name).exists():
            raise SystemExit("REFUSED: zoo/%s exists already; nothing written" % name)
    v = REPO / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = REPO / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("Zoo %s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in zoo/: the "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
